/**
 * GATE L2-A — THE SKILL TABLE IS CONTRACT (lane L2).
 *
 * `OG_SKILLS` is generated by `scripts/payload/transcribeSkills.py` from the
 * payload's own `skilldata.xml` — never hand-keyed (GAUNTLET.md §2, "a script
 * beats a swarm"). This file is the trust, in the same two-part shape
 * `tests/a11AnimData.test.ts` earned:
 *
 *   1. STRUCTURAL PINS that run everywhere, with no reference payload present.
 *   2. A BYTE-CHECK that re-parses the SOURCE with its own INDEPENDENT grammar
 *      — raw-text regex here, versus ElementTree in the generator — and demands
 *      the committed table match field for field. A shared parser would only
 *      prove the two agree with each other.
 *
 * Grammar facts pinned (probed 2026-08-24, this commit's skilldata.xml):
 *   - 75 skills, 182 level rows, ids unique, categories 1..11.
 *   - <passive> is present-and-'1' or absent; it is NEVER '0'.
 *   - An EMPTY tag is ABSENT DATA, not zero — 101 empty <chi>, 84 empty
 *     <cooldown>, 47 empty <desc>, 2 empty <required>.
 *   - <req> is a PREREQUISITE TREE, not an empty tag:
 *     <req><has><id>N</id><qty>M</qty></has></req> on 52 skills. The first cut of
 *     the generator read it as a scalar (ElementTree .text is empty when the data
 *     is in children) and silently dropped all 52 — caught by the closed-vocabulary
 *     check below, which saw a <qty> tag the generator never walked. That is the
 *     whole reason this byte-check uses an INDEPENDENT parser.
 *   - Cooldowns are SECONDS and exactly one is fractional: Roll (1004) L2 = 3.5.
 *
 * ⚠️ C2 — these rows are the ANDROID build (v0.682); no web-side artifact
 * corroborates them yet (GAUNTLET.md §2.1).
 */
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { OG_SKILLS, type OgSkill, type OgSkillLevel } from '../src/config/ogSkills';
import { SKILL_COOLDOWN_MS } from '../src/config/skills';

describe('L2-A structural pins — run everywhere, no reference payload needed', () => {
  it('carries exactly 75 skills and 182 level rows', () => {
    expect(OG_SKILLS.length).toBe(75);
    expect(OG_SKILLS.reduce((n, s) => n + s.levels.length, 0)).toBe(182);
  });

  it('every skill id is unique', () => {
    const ids = OG_SKILLS.map((s) => s.id);
    expect(new Set(ids).size).toBe(ids.length);
  });

  it('every category is an integer in 1..11', () => {
    for (const s of OG_SKILLS) {
      expect(Number.isInteger(s.category), `skill ${String(s.id)}`).toBe(true);
      expect(s.category).toBeGreaterThanOrEqual(1);
      expect(s.category).toBeLessThanOrEqual(11);
    }
  });

  it('levels-per-skill matches the source distribution: 43×1, 18×3, 9×5, 4×10, 1×0', () => {
    const dist = new Map<number, number>();
    for (const s of OG_SKILLS) dist.set(s.levels.length, (dist.get(s.levels.length) ?? 0) + 1);
    expect(dist.get(1)).toBe(43);
    expect(dist.get(3)).toBe(18);
    expect(dist.get(5)).toBe(9);
    expect(dist.get(10)).toBe(4);
    expect(dist.get(0)).toBe(1);
  });

  it('level values run 1..n with no gaps, in order', () => {
    for (const s of OG_SKILLS) {
      expect(s.levels.map((l) => l.value), `skill ${String(s.id)}`).toEqual(
        s.levels.map((_, i) => i + 1),
      );
    }
  });

  it('optional fields are ABSENT, never zero-defaulted — the source had empty tags', () => {
    const count = (pick: (l: OgSkillLevel) => number | undefined): number =>
      OG_SKILLS.flatMap((s) => s.levels).filter((l) => pick(l) === undefined).length;
    expect(count((l) => l.chi)).toBe(101);
    expect(count((l) => l.cooldownS)).toBe(84);
    expect(count((l) => l.descId)).toBe(47);
    expect(count((l) => l.required)).toBe(2);
  });

  it('exactly one cooldown is fractional — Roll (1004) level 2 = 3.5 s', () => {
    const fractional = OG_SKILLS.flatMap((s) =>
      s.levels
        .filter((l) => l.cooldownS !== undefined && !Number.isInteger(l.cooldownS))
        .map((l) => ({ id: s.id, value: l.value, cd: l.cooldownS })),
    );
    expect(fractional).toEqual([{ id: 1004, value: 2, cd: 3.5 }]);
  });

  it('27 skills are passive and passive skills never carry a cooldown', () => {
    const passives = OG_SKILLS.filter((s) => s.passive);
    expect(passives.length).toBe(27);
    for (const s of passives) {
      for (const l of s.levels) {
        expect(l.cooldownS, `passive skill ${String(s.id)} has a cooldown`).toBeUndefined();
      }
    }
  });

  it('52 prerequisites, each exactly one {id, qty} — the skill tree is captured', () => {
    const reqs = OG_SKILLS.filter((s) => s.requires !== undefined);
    expect(reqs.length).toBe(52);
    for (const s of reqs) {
      expect(Number.isInteger(s.requires?.id), `skill ${String(s.id)}`).toBe(true);
      expect(s.requires?.qty).toBeGreaterThan(0);
    }
    // Two id spaces the source does not distinguish, recorded and NOT interpreted.
    const ids = [...new Set(reqs.map((s) => s.requires?.id))].filter(
      (id): id is number => id !== undefined,
    );
    const skillIds = new Set(OG_SKILLS.map((s) => s.id));
    const foreign = ids.filter((id) => !skillIds.has(id)).sort((a, b) => a - b);
    expect(foreign).toEqual([28, 29, 30, 31]);
  });

  it('73 of 75 skills resolved a name, 0 misses — the string table is live', () => {
    expect(OG_SKILLS.filter((s) => s.name !== undefined).length).toBe(73);
  });

  it('the shipped cooldowns are DERIVED from the table, not hand-picked', () => {
    const level1S = (id: number): number | undefined =>
      OG_SKILLS.find((s) => s.id === id)?.levels[0]?.cooldownS;
    // Config may hold no logic, so these are literals there — this is the ratchet
    // that makes them literals OF THE SOURCE rather than of somebody's memory.
    expect(SKILL_COOLDOWN_MS.chiPunch).toBe((level1S(1042) ?? NaN) * 1000);
    expect(SKILL_COOLDOWN_MS.smokeBomb).toBe((level1S(1010) ?? NaN) * 1000);
    // `stab` is deliberately NOT derived: the OG skill it names is a passive with
    // no cooldown, so 920 ms is authored. Pinned as a divergence, not a source value.
    expect(level1S(1018)).toBeUndefined();
    expect(SKILL_COOLDOWN_MS.stab).toBe(920);
  });

  it('the three skills the duel already ships resolve to their payload rows', () => {
    const by = (id: number): OgSkill => {
      const s = OG_SKILLS.find((x) => x.id === id);
      if (s === undefined) throw new Error(`no skill ${String(id)}`);
      return s;
    };
    // Chi Punch — 3 levels, 5 s cooldown, 2 chi.
    expect(by(1042).name).toBe('Chi Punch');
    expect(by(1042).levels.map((l) => l.cooldownS)).toEqual([5, 5, 5]);
    // Smoke Bomb — cooldown DROPS at level 3.
    expect(by(1010).name).toBe('Smoke Bomb');
    expect(by(1010).levels.map((l) => l.cooldownS)).toEqual([6, 6, 5]);
    // Stab is PASSIVE in the original and has no cooldown at all (DIVERGENCES).
    expect(by(1018).name).toBe('Stab');
    expect(by(1018).passive).toBe(true);
    expect(by(1018).levels.every((l) => l.cooldownS === undefined)).toBe(true);
  });
});

/** The byte-check proper — parses the payload with its own independent grammar. */
const SKILLDATA = path.join(
  fileURLToPath(new URL('..', import.meta.url)),
  'reference',
  'extracted',
  'skilldata.xml',
);
const HAVE_SOURCE = existsSync(SKILLDATA);

describe.skipIf(!HAVE_SOURCE)('L2-A byte-check — OG_SKILLS is a faithful transcription', () => {
  /** Raw-text regex, deliberately NOT the generator's DOM parser. */
  const one = (body: string, tag: string): string | undefined => {
    const all = [...body.matchAll(new RegExp(`<${tag}>([\\s\\S]*?)</${tag}>|<${tag}\\s*/>`, 'g'))];
    if (all.length === 0) return undefined;
    if (all.length > 1) throw new Error(`<${tag}> appears ${String(all.length)}x`);
    const raw = all[0]?.[1];
    const trimmed = (raw ?? '').trim();
    return trimmed === '' ? undefined : trimmed;
  };

  // `describe.skipIf` skips the tests but RUNS this body — guard the read.
  const raw = HAVE_SOURCE ? readFileSync(SKILLDATA, 'utf8') : '';
  const blocks = [...raw.matchAll(/<skill>([\s\S]*?)<\/skill>/g)].map((m) => m[1] ?? '');

  it('the source itself holds 75 <skill> blocks and 182 <level> blocks', () => {
    expect(blocks.length).toBe(75);
    expect([...raw.matchAll(/<level>/g)].length).toBe(182);
  });

  it('every committed skill matches the source field for field', () => {
    expect(blocks.length).toBe(OG_SKILLS.length);

    blocks.forEach((block, i) => {
      const committed = OG_SKILLS[i];
      if (committed === undefined) throw new Error(`no committed skill at index ${String(i)}`);
      const where = `skill index ${String(i)} (id ${String(committed.id)})`;

      // Scalar lookups must see ONLY the skill's own direct fields. Strip the
      // <level> children and the <req> subtree — <req><has><id>… nests a SECOND
      // <id>, which would otherwise be read as the skill's own id.
      const head = block
        .replace(/<level>[\s\S]*?<\/level>/g, '')
        .replace(/<req>[\s\S]*?<\/req>/g, '');
      const reqBlock = /<req>[\s\S]*?<\/req>/.exec(block)?.[0] ?? '';

      expect(Number(one(head, 'id')), `${where}: id`).toBe(committed.id);
      expect(Number(one(head, 'category')), `${where}: category`).toBe(committed.category);
      expect(one(head, 'passive') === '1', `${where}: passive`).toBe(committed.passive);

      const optInt = (tag: string, got: number | undefined): void => {
        const src = one(head, tag);
        expect(src === undefined ? undefined : Number(src), `${where}: ${tag}`).toBe(got);
      };
      optInt('order', committed.order);
      optInt('lvlreq', committed.levelReq);
      optInt('displayname', committed.displaynameId);
      optInt('desc', committed.descId);

      const reqMatch = /<req><has><id>(\d+)<\/id><qty>(\d+)<\/qty><\/has><\/req>/.exec(reqBlock);
      if (reqMatch === null) {
        expect(committed.requires, `${where}: unexpected prerequisite`).toBeUndefined();
      } else {
        expect(committed.requires, `${where}: prerequisite`).toEqual({
          id: Number(reqMatch[1]),
          qty: Number(reqMatch[2]),
        });
      }

      const levels = [...block.matchAll(/<level>([\s\S]*?)<\/level>/g)].map((m) => m[1] ?? '');
      expect(levels.length, `${where}: level count`).toBe(committed.levels.length);

      levels.forEach((lvl, j) => {
        const row = committed.levels[j];
        if (row === undefined) throw new Error(`${where}: no committed level ${String(j)}`);
        const at = `${where} level ${String(j + 1)}`;
        expect(Number(one(lvl, 'value')), `${at}: value`).toBe(row.value);
        const optLvl = (tag: string, got: number | undefined): void => {
          const src = one(lvl, tag);
          expect(src === undefined ? undefined : Number(src), `${at}: ${tag}`).toBe(got);
        };
        optLvl('required', row.required);
        optLvl('chi', row.chi);
        optLvl('desc', row.descId);
        optLvl('cooldown', row.cooldownS);
      });
    });
  });

  it('no source field is silently dropped — the tag vocabulary is closed', () => {
    const tags = new Set([...raw.matchAll(/<(\w+)>/g)].map((m) => m[1]));
    expect([...tags].sort()).toEqual(
      ['category', 'chi', 'cooldown', 'desc', 'displayname', 'has', 'id', 'level',
        'lvlreq', 'order', 'passive', 'qty', 'req', 'required', 'skill', 'skilldata',
        'value'].sort(),
    );
  });
});
